def find_components(grid, val):
    rows, cols = len(grid), len(grid[0])
    comps = []
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == val and (r,c) not in visited:
                comp = []
                stack = [(r,c)]
                while stack:
                    nr, nc = stack.pop()
                    if (nr, nc) in visited:
                        continue
                    visited.add((nr, nc))
                    comp.append((nr, nc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        r2,c2 = nr+dr, nc+dc
                        if 0<=r2<rows and 0<=nc2<cols and grid[r2][c2]==val and (r2,c2) not in visited:
                            visited.add((r2,c2))
                            stack.append((r2,c2))
                comps.append(comp)
    return comps

